// Parse WorldBank — fix: n8n HTTP node may return string
const yieldRaw = $('Fetch Cereal Yield').first().json;
const prodRaw = $('Fetch Cereal Production').first().json;

const rows = [];

// Helper: parse WorldBank response (handles string or object)
function parseWB(raw) {
  let data = raw;
  if (typeof raw.data === 'string') data = JSON.parse(raw.data);
  else if (raw.data) data = raw.data;
  const arr = Array.isArray(data) ? data[1] : (data && data[1] ? data[1] : []);
  if (arr && Array.isArray(arr)) {
    return arr.find(r => r.value !== null && r.value !== undefined);
  }
  return null;
}

// 1. Cereal Yield
const yieldLatest = parseWB(yieldRaw);
if (yieldLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Rice', metric: 'cereal_yield', value: Math.round(yieldLatest.value * 100) / 100, unit: 'kg/ha', period: yieldLatest.date });
}

// 2. Cereal Production
const prodLatest = parseWB(prodRaw);
if (prodLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Rice', metric: 'cereal_production', value: Math.round(prodLatest.value), unit: 'tonnes', period: prodLatest.date });
}

if (rows.length === 0) {
  return [{ json: { source: 'WorldBank', commodity: 'Rice', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
